   "name": "min_rating",
   "type": "integer",
   "required": false,
   "description": "The minimum rating for a review.",
   "default": 1,
   "constraints": [
    "value >= 1, <= 5"
   ]
  },
  {
   "name": "max_rating",
   "type": "integer",
   "required": false,
   "description": "The maximum rating for a review.",
   "default": 5,
